using System;
using System.Collections.Generic;
using System.Linq;

namespace PCShopSell.Core.Session
{
    public static partial class CityLifeCatalog
    {
        private static void ConfigureExistingNarrativePeople(List<CityPersonDefinition> people)
        {
            void History(string id,string title,string a,string b,string c)
            {
                var p=people.First(x=>x.Id==id);p.StoryTitle=title;p.Experience=a;p.Stories=new[]{a,b,c};
                p.Topics=new[]{a,"我喜欢"+p.Interest+"。",p.Goal,c};
            }
            void Place(string id,string home,string work,int start=540,int end=1080)
            {var p=people.First(x=>x.Id==id);p.HomeId=home;p.WorkId=work;p.WorkStart=start;p.WorkEnd=end;}
            foreach(var row in new[]{
                new[]{"landlady","52","照看老房子和种花","把房屋维护和租约交代清楚，也给自己留些休息时间。"},
                new[]{"lin","29","玩游戏和约老朋友吃饭","工作稳定以后，还能和老朋友认真见面。"},
                new[]{"zhou","48","旧电子设备和听评书","把熟人的信任和自己能承担的风险分清楚。"},
                new[]{"jie","32","拆手机和街边小吃","守好自己的店，不为扩张压垮原有生活。"},
                new[]{"li","45","钓鱼和研究硬件","让老客户放心，也给新店一次靠谱合作的机会。"},
                new[]{"wang","36","研究显卡和逛市场","消息说清来处，不再拿猜测当保证。"},
                new[]{"qian","41","记账和看老电影","经营稳妥，也能按时下班。"},
                new[]{"sun","56","修电器和听球赛","教会年轻人先把质量和承诺说清楚。"},
                new[]{"zhang","62","读书和写短篇","在附近留一个愿意坐下读书的角落。"},
                new[]{"keeper_agent","30","走街看建筑和拍门头","让签约的人知道自己签下的责任。"}})
            {var p=people.First(x=>x.Id==row[0]);p.Age=int.Parse(row[1]);p.Interest=row[2];p.Goal=row[3];}
            History("landlady","下一次续租","这几间房是父亲留下的。第一次独自处理漏水，我才知道租约上的几句话背后有多少具体事情。","有一年租户周转不开，我同意分两次交。他后来按时补齐，也有别人拖着不回话，所以我现在先把日期写清楚。","如果你以后也收租，别急着回答别人没办法。先听完事情，再决定自己愿意承担多少，承诺了就照着做。");
            History("keeper_agent","带你进门的人","刚做中介时我只会背面积和租金，一位店主问卸货车能不能停，我竟没去看过门口。","后来每带人看铺，我都会走一次进货路线。李姐介绍新人，我也会讲清押金和退租，不拿熟人当省略条件的理由。","现在我能把人介绍给唐蔚，但不能替她承诺好铺位。介绍打开的是谈话，合不合适还得双方自己判断。");
            History("lin","你现在说话像个老板了","我们小时候常把河边的空地当球场，谁带球谁也不能一直霸着不传。现在你开店，我还是记得那时候的事。","有次我抱怨临时加班，你先替老板算了一遍成本。我知道你没恶意，就是有点意外，原来我们现在先想到的东西不同。","我也想换一份更合适的工作，但不想每次找你都像求照顾。一起吃顿饭，说点不需要解决的事，也挺好。");
            History("zhou","我只能替认识的人担保","我最早在市场搬货，第一次独立接单，没有人肯让我赊。我至今记得那位愿意先给我两箱试卖的老板。","后来替一个不熟的人担保，对方失约，我自己补上差额。从此介绍人之前，总要知道他做过什么。","新人问我没有机会怎么证明自己，我答不上来一句万用的话。现在会从小单开始，先讲清风险，不把门一口关死。");
            History("jie","我当年也是这么熬过来的","我攒够第一间店的押金时，以为最难的已经过去。真正开门以后，才知道每个月都要再过一遍。","我们一起熬过冷清的时候，我当然替你高兴。可有人提议给新店更多优惠，我也会想到自己当初付过的代价。","我不想被说成见不得新人好，也不想别人轻易拿走我熬出来的位置。真要改条件，至少让我把担心说完。");
            History("li","一张靠谱的交货单","学做配件时，我先学的是把客户用途问清楚。跑分再好，装不上客户的机器也没用。","有次库存晚到，我提前给沈远说明了替代方案。他没有立刻答应，但后来愿意继续找我。","我现在介绍小店去接试单，不夸他什么都能做。说清能交什么、什么时候交，已经很难得。");
            History("wang","消息比货跑得快","我刚开显卡档口时喜欢抢着报消息，别人围过来听，会让我觉得自己有本事。","一次把没确认的涨价当真，几个熟客跟着囤货。我没法替他们全赔，只能承认消息出处不可靠。","现在还是爱说话，但会补一句哪部分只是听说。别人愿不愿意信，至少得知道我究竟知道多少。");
            History("qian","一分钱也有来处","刚帮家里做生意时，我每天对账到很晚，怕少了一分钱就说明自己做不好。","后来有笔借调库存对不上，我和盘点员一起找记录。看见完整经过，比逼着一个人认错更有用。","我仍然喜欢清楚的账，但也开始给自己留休息时间。账本要帮人过日子，不该把日子全吃掉。");
            History("sun","先把话说在前面","我以前跟车送电源和机箱，路上箱子压坏了，客户只认货到了什么样。","有次为了赶货省了包装，后面退换花了更久。那以后不随便承诺当天一定到。","儿子也在学维修，我告诉他不会就问。客户买的是能用的东西，不是你逞强的样子。");
            History("zhang","这里还有我的位置","年轻时想当作家，稿子退过几次，后来读师范，一教就是二十五年。","学生有人继续读书，有人很早工作。我没有一张表能把他们排成谁更成功，能偶尔听见近况就好。","退休后想弄个小小的读书角，不一定是自己的店。有人愿意坐下看两页，那里就有一点像我想象的书店。");
            History("momo","这次先按合作方的要求","最早拍教程时只有几个朋友看，我把一个拆装步骤录了七遍，怕新人照着做会弄坏。","后来合作方希望我少提缺点，报酬确实能缓解房租。我第一次明白，知道边界和守住边界不是一回事。","我想继续接合作，也想把实际测过什么说清楚。朋友愿意看我的内容，不该成为替别人保证一切的筹码。");
            History("ake","镜头关掉以后","刚开始直播，我以为一直热闹才能留住人，连嗓子不舒服也不敢停。","一次设备故障，观众反而在聊天里问我吃饭没有。我才发现屏幕另一边不全是催我表现的人。","现在播完会真的关掉镜头，和朋友打一局不计成绩的游戏。我还想进步，但不想只有开播时才像自己。");
            History("qiao","把测试记录留下","第一篇评测我只记了最漂亮的一组数据，评论问重复测试时，我拿不出完整记录。","后来样机出问题，合作方希望删掉那段。我重新整理测试过程，先把能确认和不能确认的分开。","现在有人因为我没说好话取消合作，也有人因为记录清楚找过来。我愿意慢慢把这种信任做出来。");
            History("staff_cpu","把用途问清楚","刚到CPU档口我背了一整本型号，客人问旧电脑能不能升级，我却不会问主板是什么。","老李带我核对接口，也让我承认不知道。那次客人没有嫌慢，反而下次带朋友来。","我想把常见问题整理成几张卡片，后来的新店员不用先受一遍同样的窘。");
            History("staff_gpu","退回来的那一张","刚做售后时，我总想尽快证明不是我们的货有问题。","有张显卡在店里正常，到客户家就出错。多问了供电和机箱情况，才找到真正原因。","现在遇到退货先听完经过，不急着抢一句结论。解决一件事比辩赢省心。");
            History("staff_mem","小票背面的记号","我最初用小票背面记临时借出去的样条，收摊时纸越堆越多。","钱姐教我把交接集中起来，我才发现记得很多和能让别人接着做是两回事。","最近准备学一点库存表格，希望请假一天也不用接十几个问东西在哪的电话。");
            History("staff_psu","第一次独自交货","第一次送大机箱，我只算了路程，到了楼下才知道没有电梯。","搬完那趟手都抬不起来，老孙让我下次先问清楼层，不要只答应快。","现在新同事跟我送货，我先教他问卸货位置。把事问全，不算偷懒。");
            History("keeper_phone","修好之后","开始卖手机时，我以为把参数讲全就算负责。","一位老人回来三次问怎么放大字，我才把常用操作写成了大字卡。","现在卖完会问一句能不能自己操作。我想学维修，也想把说明讲得更容易懂。");
            History("keeper_mall","先量门再挑柜子","第一周上班卖出一张大柜子，很开心，送到家却进不了楼道。","周敏带我一起去处理退换，我记住的不只是运费，还有客户腾空房间白等一天。","现在先问楼道和门宽。少卖一次不合适的柜子，比事后说抱歉轻松。");
            History("staff_mall","摆得下也要用得着","做家具店员时我最喜欢介绍大的，觉得大就能让人觉得值。","一位顾客说柜门打不开，我去现场才发现尺寸对了，生活的动线却没留。","如今培训新人先让他们想象人在房里怎么走。房间不是把目录里所有东西塞满就好了。");
            History("keeper_tobacco","熟客的那句话","我守店多年，客人什么时候来、爱坐哪张椅子，慢慢都记住了。","有次熟客提起家里的难处，我顺口告诉下一位，被他听见后很久没再来。","现在知道的事不一定该说。可以记得他爱喝什么，不替他把私事讲出去。");
            History("keeper_farm","今天这批菜","刚摆摊时最怕有货卖不完，总把明天会不会涨价挂在嘴边。","一次天气不好，菜到得晚，我只能逐个告诉熟客少了什么，而不是先把钱收下。","如今会把当天能供的写清楚。小馆子按这张单备料，我不能让他们开火后才发现不够。");
            History("keeper_dealer","一辆车能做什么","以前我介绍车总先说速度，送货的人却更关心能不能放下几箱货。","一位熟客买大了，停车和油费压得难受，我才开始先问他每天实际跑哪条路。","现在修车顺便听听他们怎么用。车不是买得越贵，日子就越轻松。");
            History("staff_gpu2","箱子上的箭头","第一次打包时我觉得向上箭头只是装饰，哪面平就往哪面放。","到货坏了两件，我跟着拆箱看见内部支撑的方向，才知道标记不是写给别人看的。","现在每箱装完会自己提起来试一下，想学会完整负责一趟出货。");
            History("keeper_phone2","别急着动烙铁","我刚学维修时恨不得马上碰最复杂的机器，觉得换屏太普通。","小唐让我先把每颗螺丝放回原位，一部简单的手机也花了我很久。","现在想先练稳基础。能把客人的东西完整交回去，就已经是实实在在的本事。");
            History("staff_mall2","抬起来之前","我以前搬东西总觉得自己力气大，招呼都不打就先抬一头。","有次和同事不同步，柜角碰坏了。周敏让我们先说方向和停的位置，再一起动。","现在新来的人我都会提醒先开口。合作有时不是多使一点力，而是多说一句。");
            History("life_model_supplier","把版本说清楚","我最早替模型店整理价签，分不清初版和再版，闹过一次退换。","后来把底座标记、包装和制作年份一起记下，陆栀与程弈会帮我核对不确定的地方。","现在有人问停产款，我会先确认他到底喜欢哪一点。找不到就直说，不把相似款冒充旧版。");
            var titles=new Dictionary<string,string>{{"life_creator","我已经不喜欢那个角色了"},{"life_ming","第二块招牌"},{"life_ning","夜校的那盏灯"},{"life_qiao","路线册之外"},{"life_enterprise","孩子一直惦记的那一件"},{"life_tenant","下一次续租"},{"life_curator","名单上还有谁"},{"life_maker","旧展品的新底座"},{"life_clothier","看起来像那么回事"},{"life_designer","衣服里的自己"},{"life_chef","这里还有我的位置"},{TangWei,"把大家的事办成"},{LiangJing,"我们一直都这么办"},{ShenXiao,"窗边的小凳子"}};
            foreach(var t in titles)people.First(p=>p.Id==t.Key).StoryTitle=t.Value;
            Place("landlady","life_home_s_oldhomes","life_home_s_oldhomes",540,660);
            Place("lin","life_home_s_oldhomes","life_company",540,1080);
            Place("zhou","life_home_s_oldhomes","stall_cpu",540,1020);
            Place("zhang","life_home_s_services","life_service",480,960);
            Place("life_enterprise","life_home_s_services","life_company");
            Place("life_curator","life_home_s_sports","life_expo");
            Place("life_maker","life_home_s_creative","model_workshop");
            Place("life_creator","life_home_s_creative","life_studio",600,1080);
            Place(ShenXiao,"life_home_s_services","life_service",480,960);
            foreach(var id in new[]{"life_curator",LiangJing})people.First(p=>p.Id==id).LeisurePlaces=new[]{"life_restaurant_tier3","life_bar_tier4","life_expo"};
            people.First(p=>p.Id==ShenXiao).LeisurePlaces=new[]{"life_service","life_court","life_market"};
            var encounters=new Dictionary<string,string>{{"landlady","入住出租屋时认识；经营达到规模后，她会介绍社区商户。"},{"keeper_agent","第一次看铺签约时认识，负责租约与地点接洽。"},{"lin","开局已有的老朋友，不以主线晋升为相识条件。"},{TangWei,"李姐和小陈介绍的社区运营联系人，也可提前在社区中介碰面。"},{"life_curator","在社区联合活动筹备时正式合作，平时在会展中心工作。"},{"life_enterprise","经任帆介绍后在饭局交谈，不要求玩家经营电脑店。"},{LiangJing,"任帆介绍的花园经营者；此前可以见面，行业成就达标后才谈大合作。"},{"life_creator","通过创作圈或旧展品线索相识，商业与私人关系分别发展。"},{"life_ming","应聘或兴趣相处时认识，创业愿望在长期工作后再谈。"}};
            foreach(var e in encounters)people.First(p=>p.Id==e.Key).FirstEncounter=e.Value;
        }
    }
}
